<?php
namespace App\Services;
use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Storage;
class MedicationEvidenceService { public function store(UploadedFile $file,int $patientId,string $watermark): string { if(!function_exists('imagewebp'))throw new \RuntimeException('Ekstensi GD/WebP diperlukan.');$image=$file->getMimeType()==='image/webp'?imagecreatefromwebp($file->getRealPath()):imagecreatefromjpeg($file->getRealPath());$w=imagesx($image);$lines=explode("\n",wordwrap($watermark,max(20,(int)($w/12)),"\n"));$h=count($lines)*22+18;$black=imagecolorallocatealpha($image,0,0,0,48);imagefilledrectangle($image,0,imagesy($image)-$h,$w,imagesy($image),$black);$white=imagecolorallocate($image,255,255,255);foreach($lines as $i=>$line)imagestring($image,5,10,imagesy($image)-$h+9+$i*20,$line,$white);ob_start();imagewebp($image,null,85);$bin=ob_get_clean();imagedestroy($image);$path="medication-reports/$patientId/".now()->format('Y/m').'/'.bin2hex(random_bytes(16)).'.webp';Storage::disk('local')->put($path,$bin);return $path;} }
